package ru.mathdatum.localization

class XyzCase(val ellipsoid: String, val lat: Double, val lon: Double, val h: Double,
              val x: Double, val y: Double, val z: Double)

class TransformCase(val from: String, val to: String, val steps: Int, val x: Double, val y: Double, val z: Double,
                    val ex: Double, val ey: Double, val ez: Double)

/** zone = 0 — зона по долготе. */
class GkCase(val ellipsoid: String, val zone: Int, val lat: Double, val lon: Double, val x: Double, val y: Double)

class TmProjCase(val ellipsoid: String, val lon0: Double, val lat0: Double, val k0: Double, val x0: Double,
                 val y0: Double, val lat: Double, val lon: Double, val x: Double, val y: Double)

/** Строки: B, L, H (СК-42), XYZ СК-42, XYZ ПЗ-90.11 из задачи, XYZ ПЗ-90.11 по Python; первые 5 — exact, затем noisy. */
class RegionHelmert(val iso: String, val rows: List<DoubleArray>)

/** expected — как у RegionCase; check — контрольные пункты в ПЗ-90.11, local — их to_local(datum = ПЗ-90.11),
 *  back — to_wgs(local, datum = WGS-84). */
class GnssDatumCase(val iso: String, val system: String, val ellipsoid: String, val pairs: List<LocalizationPair>,
                    val expected: DoubleArray, val check: List<DoubleArray>, val local: List<DoubleArray>,
                    val back: List<DoubleArray>)

